using DataOrganizer.TestSupport.Guards;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using System;
using System.Collections.Generic;
using System.Linq;

namespace DataOrganizer.GuardTests.TestHelpers;

/// <summary>
/// The syntax trees of the hand-written C# files of the application and of the tests.
/// </summary>
internal static class SourceSyntax
{
	#region Data
	/// <summary>
	/// Marker that a tool writes at the top of a generated file.
	/// </summary>
	private const string GeneratedMarker = "<auto-generated";

	/// <summary>
	/// Folder of the migrations that Entity Framework scaffolds without the generated marker.
	/// </summary>
	private const string MigrationsFolder = "src/DataOrganizer.Database.Migrations/Migrations/";

	/// <summary>
	/// Options that accept every feature of the language the build compiles.
	/// </summary>
	private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Preview);

	/// <summary>
	/// The syntax trees, parsed once.
	/// </summary>
	private static readonly Lazy<SyntaxTree[]> Trees = new(Parse);
	#endregion

	#region Methods
	/// <summary>
	/// Gets the syntax trees, each with its repository-relative path written with forward slashes as its file path.
	/// </summary>
	public static IReadOnlyList<SyntaxTree> GetTrees() => Trees.Value;
	#endregion

	#region Helpers
	/// <summary>
	/// Tells whether a tool wrote a file: a comment before its first token holds the generated marker.
	/// </summary>
	private static bool IsGenerated(SyntaxTree tree)
	{
		return tree
			.GetRoot()
			.GetLeadingTrivia()
			.Any(static x => x.IsKind(SyntaxKind.SingleLineCommentTrivia) && x.ToString().Contains(GeneratedMarker, StringComparison.Ordinal));
	}

	/// <summary>
	/// Parses every C# file of the source and tests folders, the generated ones left out.
	/// </summary>
	private static SyntaxTree[] Parse()
	{
		(string FilePath, string Text)[] files =
		[
			.. RepositoryFiles
				.EnumerateSourceCode()
				.Select(static x => (FilePath: $"{RepositoryFiles.SourceFolder}/{x.FilePath}", x.Text)),
			.. RepositoryFiles
				.EnumerateTestCode()
				.Select(static x => (FilePath: $"{RepositoryFiles.TestsFolder}/{x.FilePath}", x.Text))
		];

		return
		[
			.. files
				.Where(static x => !x.FilePath.StartsWith(MigrationsFolder, StringComparison.Ordinal))
				.Select(static x => CSharpSyntaxTree.ParseText(x.Text, ParseOptions, x.FilePath))
				.Where(static x => !IsGenerated(x))
		];
	}
	#endregion
}
